-- Function: public.fn_get_users_by_role
-- Backup generated on 2026-10-25 20:33:44

CREATE OR REPLACE FUNCTION public.fn_get_users_by_role(p_tenant_id uuid, p_role_name character varying, p_names character varying[])  RETURNS TABLE(id uuid, tenant_id uuid, email character varying, first_name character varying, last_name character varying, display_name character varying, is_active boolean, created_at timestamp with time zone, updated_at timestamp with time zone)  LANGUAGE plpgsql AS $function$ BEGIN     RETURN QUERY     SELECT u.id, u.tenant_id, u.email, u.first_name, u.last_name, u.display_name, u.is_active, u.created_at, u.updated_at     FROM users u     WHERE u.tenant_id = p_tenant_id       AND (EXISTS (SELECT 1 FROM user_roles ur JOIN roles r ON ur.role_id = r.id                    WHERE ur.user_id = u.id AND r.name = p_role_name)            OR EXISTS (SELECT 1 FROM user_organization_roles uor JOIN roles r ON r.id = uor.role_id                       WHERE uor.user_id = u.id AND uor.tenant_id = p_tenant_id AND r.name = ANY(p_names)))     ORDER BY u.first_name, u.last_name; END; $function$ ;
